export function makeBandMatrix(values: readonly number[], offset: number): number[][] {
  if (!Number.isInteger(offset) || !Number.isFinite(offset) || values.some(value => !Number.isFinite(value))) {
    throw new TypeError("values and offset must be finite");
  }
  if (values.length === 0) return [];
  const size = values.length + Math.abs(offset);
  const row = Array<number>(size).fill(0);
  const matrix = Array<number[]>(size).fill(row);
  for (let i = 0; i < values.length; i++) {
    const r = offset >= 0 ? i : i - offset;
    const c = offset >= 0 ? i + offset : i;
    matrix[r][c] = values[i];
  }
  return matrix;
}
```

