import { makeBandMatrix } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function matrixEqual(actual: number[][], expected: number[][], message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}
function throwsTypeError(action: () => unknown, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: expected TypeError`); }
  throw new Error(`${message}: expected throw`);
}

const values = [4, 5, 6];
const before = values.slice();
const main = makeBandMatrix(values, 0);
matrixEqual(main, [[4, 0, 0], [0, 5, 0], [0, 0, 6]], 'zero offset diagonal');
matrixEqual([values], [before], 'input is not mutated');

const upper = makeBandMatrix([1, 2], 2);
matrixEqual(upper, [
  [0, 0, 1, 0],
  [0, 0, 0, 2],
  [0, 0, 0, 0],
  [0, 0, 0, 0]
], 'positive offset band');

const lower = makeBandMatrix([7, 8], -2);
matrixEqual(lower, [
  [0, 0, 0, 0],
  [0, 0, 0, 0],
  [7, 0, 0, 0],
  [0, 8, 0, 0]
], 'negative offset band');

upper[0][0] = 99;
equal(upper[1][0], 0, 'matrix rows do not alias');
equal(upper[2][0], 0, 'all rows are independent');

matrixEqual(makeBandMatrix([], 0), [], 'empty input at zero offset');
matrixEqual(makeBandMatrix([], 100), [], 'empty input ignores positive offset in result');
matrixEqual(makeBandMatrix([], -100), [], 'empty input ignores negative offset in result');

for (const offset of [1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  throwsTypeError(() => makeBandMatrix([1], offset), `invalid offset ${String(offset)}`);
}
for (const bad of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  throwsTypeError(() => makeBandMatrix([1, bad, 2], 0), `invalid value ${String(bad)}`);
}
throwsTypeError(() => makeBandMatrix([], Number.NaN), 'invalid offset is rejected even for empty input');

